#include "stdafx.h"#include "ALM.h"KALM::KALM(): m_CurParameterID(-1), m_ReadParams( 0 ){}static LPCSTR s_MyParameters[]={  "Local Setpoint",  "Use remote setpoint",  "Latch",  "Hysteresis",  "Type",  "On Delay",};BOOL KALM::OnParsingSingleText( std::string &szText, RECTL *rc ){    if( m_CurParameterID!=-1 )  {    CStringA s;    if( !m_CurParameterID )      s.Format( "LocalSetpoint = %s", szText.c_str() );    else if( 1==m_CurParameterID )    {      if( !szText.compare("ON") )        s = "UseRemoteSetpoint = TRUE";      else        s = "UseRemoteSetpoint = FALSE";    }    else if( 2==m_CurParameterID )    {      if( !szText.compare("OFF") )        s = "Latch = FALSE";      else      {        ASSD( 0 );        s = "Latch = TRUE";      }    }    else if( 3==m_CurParameterID )      s.Format( "Hysteresis = %s", szText.c_str() );    else if( 4==m_CurParameterID )    {      if( !szText.compare("PV > SP") )        s = "Type = PVgrSP";      else if( !szText.compare("PV < SP") )        s = "Type = PVsmSP";      else      {        ASSD( 0 );      }    }    else if( 5==m_CurParameterID )      s.Format( "OnDelay = %s", szText.c_str() );    if( !s.IsEmpty() )      m_settings.push_back( s.GetBuffer() );    AddParam( s_MyParameters[m_CurParameterID], szText.c_str() );    m_CurParameterID = -1;    m_ReadParams++;    return TRUE;//сделать преобразование параметра к виду, пригодному для формирования исполняемого кода  }  for( int i=0; i<_countof(s_MyParameters); i++ )  {    if( szText.find(s_MyParameters[i])==0 )    {      m_CurParameterID = i;      return TRUE;    }  }  return FALSE;}